            "Broncopneumonia é diferente: o processo começa nos bronquíolos e se espalha por múltiplos focos. Na radiografia, vira mosaico — manchas algodonosas hilhares ou centrais que podem coalescer, pegar os dois pulmões e não respeitar fissura. O pneumococo é o patógeno que mais costuma fazer este padrão, embora muitos outros o produzam.",
            "Padrão intersticial é o terceiro grande desenho: o pulmão fica 'sujo', com linhas finas, retículos e, por vezes, nódulos. Não é específico de pneumonia: vírus (influenza, COVID-19), bactérias atípicas (micoplasma), fungos, pneumopatias intersticiais difusas e até câncer podem produzir o mesmo padrão. Vale como pista de atipia, mas nunca como confirmação."
