      "heroIntro": "Os critérios ATS/IDSA substituem ou complementam o CURB-65 na decisão de UTI. Dois critérios maiores, muito intuitivos — ventilação mecânica invasiva e choque séptico com droga vasoativa — indicam UTI diretamente. Sete critérios menores capturam a fisiologia: PaO₂/FiO₂ ≤ 250, pneumonia multilobar, confusão/desorientação, ureia alta, leucopenia, plaquetopenia, hipotermia, hipotensão que responde a volume. Um maior OU três menores puxa para a unidade crítica.",
