            "PAC ambulatorial é a maioria dos casos. A boa notícia: cobre-se empiricamente e evolui bem. A decisão fundamental é em qual 'faixa' de risco o paciente se encontra.",
            "Baixo risco: paciente previamente hígido, < 60 anos, sem comorbidades, sem uso recente de antibiótico, sem internação nos últimos 90 dias. Aqui, monoterapia oral basta: amoxicilina em alta dose (1 g 8/8 h) ou macrolídeo (azitromicina 500 mg/dia ou claritromicina 500 mg 12/12 h). A escolha entre amoxicilina e macrolídeo depende da disponibilidade, alergia e preferência local.",
