            "A doxiciclina aparece em alguns guidelines internacionais como opção monoterápica em baixo risco. No Brasil, NÃO é primeira escolha: o perfil de resistência do pneumococo local é desfavorável. Se aparecer como única alternativa em prova que segue guideline internacional, pode ser marcada como correta — mas, em cenário nacional e prática real, preferir amoxicilina ou macrolídeo."
