            "A regra padrão: ceftriaxone 1-2 g/dia IV + azitromicina 500 mg/dia IV. A ceftriaxone cobre pneumococo, hemófilo e muitos gram-negativos da comunidade. A azitromicina cobre atípicos — essencial para Legionella. A combinação é o padrão em guidelines brasileiros e internacionais.",
            "Monoterapia com β-lactâmico isolado (ceftriaxone, por exemplo) é aceita por alguns guidelines se Legionella puder ser razoavelmente excluída clinicamente — paciente sem exposição a água contaminada, sem sintomas GI, sem hiponatremia, sem sinal de Faget, sem gravidade preocupante. Armadilha: o INEP (que fazia revalidação de diploma e agora faz o ENAMED) já cobrou essa exceção, pegando alunos que marcaram 'dupla' automaticamente. A resposta depende do cenário descrito.",
            "Quinolona respiratória (levofloxacino 750 mg/dia ou moxifloxacino 400 mg/dia) isolada cobre típico e atípico — é escolha em alergia a β-lactâmico ou a macrolídeo. Efeitos adversos (delírium, tendinopatia, QT longo, disglicemia) e risco de indução de resistência pedem uso criterioso."
