      "heroIntro": "O tratamento do derrame parapneumônico segue uma escada. Derrame não complicado se resolve com antibiótico. Derrame complicado exige drenagem torácica tubular. Loculado ou empiema em fase fibrinopurulenta avançada pede fibrinolítico intrapleural (alteplase) + DNase OU toracoscopia (VATS). Pulmão encarcerado com córtex fibroso exige toracotomia e decorticação.",
