            "Derrame COMPLICADO (pH < 7,2, glicose < 40, LDH > 1000, Gram ou cultura positivos): drenagem torácica tubular é o padrão. Dreno selado em água (pleurocath ou tubo de maior calibre em empiemas). Antibiótico mantido e ajustado conforme cultura.",
