        { "label": "Proteínas de superfície", "value": "H e N", "detail": "Hemaglutinina permite entrada; neuraminidase permite saída. 18 H × 11 N." },
        { "label": "Incubação", "value": "1-4 dias", "detail": "Transmissibilidade começa 2 dias antes do início dos sintomas e vai até o 5º dia." }
