      "heroIntro": "Em epidemia, o diagnóstico de SG é clínico. Teste rápido de antígeno tem boa especificidade mas sensibilidade baixa — resultado negativo NÃO exclui influenza. PCR é o padrão-ouro. Oseltamivir 75 mg 12/12 h por 5 dias é o tratamento; benefício máximo quando iniciado nas primeiras 48 h. SRAG e grupos de risco tratam mesmo após 48 h. Zanamivir inalatório é alternativa em caso de resistência.",
