            "A janela ideal é até 48 horas do início dos sintomas — nesse intervalo, o benefício é máximo: redução de cerca de 1 dia de sintomas, menor risco de complicações, menor transmissibilidade. Depois das 48 horas, o benefício diminui, mas ainda pode haver redução de complicações em paciente grave ou em grupo de risco.",
            "Indicações OBRIGATÓRIAS (independentemente do tempo): SRAG, gestantes e puérperas (até 2 semanas), crianças < 2 anos, idosos > 60 anos, imunossuprimidos, pneumopatas, cardiopatas, diabéticos com lesão, portadores de HIV, indígenas, obesidade grave (IMC ≥ 40), doença renal crônica, doença hepática, doenças neurológicas crônicas.",
            "Zanamivir é alternativa inalatória; peramivir, IV em situação hospitalar; baloxavir, monodose oral (não disponível em todos os locais). Em resistência ao oseltamivir (rara), zanamivir é a escolha."
