      "heroIntro": "Vacinação anual é a principal medida preventiva. Vacina trivalente do SUS (2 cepas de A + 1 de B) é oferecida a grupos prioritários: crianças 6 m-5 anos, idosos ≥ 60 anos, gestantes, puérperas, profissionais de saúde, indígenas, trabalhadores de saúde, pessoas privadas de liberdade, portadores de doenças crônicas. Quando um paciente com influenza parece 'melhorar' e depois piora subitamente — com consolidação nova, leucocitose importante, piora clínica — suspeitar de coinfecção bacteriana secundária (pneumococo, S. aureus inclusive MRSA).",
