  "FLOW_CARDS": [
    {
      "title": "Suspeita e diagnóstico de pneumonia",
      "steps": [
        "Quadro respiratório agudo febril + foco ao exame físico (creptação, broncofonia).",
        "Solicitar hemograma (leucocitose com desvio) e radiografia de tórax (consolidação, broncograma).",
        "Se RX normal em alta suspeita: incidência em perfil, US pulmonar ou TC.",
        "Nomear corretamente: PAC (< 48 h admissão), PAH (≥ 48 h), PAV (≥ 48 h de VM)."
      ],
      "note": "Em discursiva, 'pneumonia' sozinho não marca — exige o sobrenome."
    },
    {
      "title": "Sítio de tratamento",
      "steps": [
        "Calcular CURB-65 (Confusão, Ureia ≥ 50, Respiração ≥ 30, Baixa PA, 65 anos).",
        "0-1 ponto: casa; ≥ 2: hospital; ≥ 3: considerar UTI.",
        "Aplicar critérios ATS/IDSA: 1 maior (VM invasiva ou choque com amina) OU 3 menores = UTI.",
        "Ajustar por contexto: saturação, rede social, comorbidades."
      ],
      "note": "Score ajuda; médico decide — o CURB-65 não manda."
    },
    {
      "title": "Cobertura empírica — PAC ambulatorial",
      "steps": [
        "Baixo risco (hígido, sem comorbidade): amoxicilina 1 g 8/8 h OU macrolídeo.",
        "Alto risco (comorbidade, idoso, ATB recente): amoxicilina-clavulanato + macrolídeo OU quinolona respiratória.",
        "Doxiciclina: armadilha no Brasil (resistência do pneumococo).",
        "Reavaliar em 48-72 h."
      ],
      "note": "Monoterapia × combinação segundo o grupo de risco."
    },
    {
      "title": "Cobertura empírica — PAC hospitalar",
      "steps": [
        "Enfermaria: ceftriaxone + azitromicina (cobertura dupla padrão).",
        "Alergia a β-lactâmico: levofloxacino OU moxifloxacino.",
        "Monoterapia β-lactâmica aceita SE Legionella excluída clinicamente (armadilha INEP).",
        "UTI: cobertura dupla OBRIGATÓRIA; MRSA/Pseudomonas por risco; hidrocortisona em grave hipoxêmico."
      ],
      "note": "UTI não admite monoterapia."
    },
    {
      "title": "PAH e PAV",
      "steps": [
        "Cobertura base anti-Pseudomonas: pipetazo OU cefepime OU carbapenêmico.",
        "MRSA por risco: vancomicina ou linezolida (pós-influenza, cateter, celulite, alta prevalência local).",
        "Alto risco de morte: duplo anti-Pseudomonas (β-lactâmico + quinolona ou aminoglicosídeo).",
        "Prevenção: cabeceira 30-45°, extubar cedo, IBP só se indicado."
      ],
      "note": "Higiene oral com clorexidina perdeu o consenso."
    },
    {
      "title": "Derrame parapneumônico",
      "steps": [
        "Clínica (dor pleurítica, frêmito reduzido, macicez) + imagem (velamento, Damoiseau).",
        "Incidência em laurel ou US para medir volume e caracterizar.",
        "Laurel > 1 cm libera toracocentese; < 1 cm observa.",
        "Amostra para proteína, LDH, glicose, pH, Gram, cultura, citologia."
      ],
      "note": "US guia punção e identifica loculação."
    },
    {
      "title": "Critérios de Light e complicação",
      "steps": [
        "Exsudato: 1 de 3 (proteína > 0,5; LDH > 0,6; LDH absoluto > 2/3 LSN).",
        "Complicado: pH < 7,2 OU glic < 40 OU LDH > 1000 OU Gram+.",
        "Empiema: pus franco ao aspecto.",
        "Loculado: septos ao US/TC."
      ],
      "note": "Diurético pode criar pseudoexsudato — gradiente albumina > 1,2 ajuda."
    },
    {
      "title": "Escada de drenagem do derrame",
      "steps": [
        "Não complicado: ATB + reavaliação.",
        "Complicado: drenagem tubular.",
        "Loculado: rtPA + DNase intrapleural (MIST-2) OU VATS.",
        "Encarcerado: toracotomia + decorticação."
      ],
      "note": "Falha em 3-5 dias escala o tratamento."
    },
    {
      "title": "Abscesso e aspiração",
      "steps": [
        "Cavidade < 2 cm em consolidação = necrosante.",
        "Cavidade ≥ 2 cm com nível hidroaéreo = abscesso — anaeróbios + flora oral.",
        "Aspiração com evolução em horas = pneumonite química (Mendelssohn) — suporte, SEM ATB rotineiro.",
        "Aspiração com evolução em dias = infecciosa — ATB anti-anaeróbio."
      ],
      "note": "Mendelssohn: horas; infecciosa: dias."
    },
    {
      "title": "Influenza — diagnóstico e tratamento",
      "steps": [
        "Definir SG (febre + 2 sintomas) × SRAG (SG + sinal de gravidade).",
        "Teste rápido: positivo confirma; negativo NÃO exclui. PCR é padrão-ouro.",
        "Oseltamivir 75 mg 12/12 h × 5 dias.",
        "SRAG e grupos de risco tratam SEMPRE, mesmo após 48 h."
      ],
      "note": "Janela de 48 h maximiza benefício em paciente sem fator de risco."
    },
    {
      "title": "Coinfecção bacteriana pós-influenza",
      "steps": [
        "Suspeitar em duplo pico (melhora → piora súbita).",
        "Imagem: nova consolidação, pneumatocele, derrame.",
        "Cobertura: β-lactâmico para pneumococo + vancomicina/linezolida se risco de MRSA.",
        "Manter oseltamivir se influenza ainda ativa."
      ],
      "note": "S. aureus (MRSA inclusive) e pneumococo são os protagonistas."
    }
  ],
