    { "kicker": "Caso 1", "sourceLabel": "PAC", "title": "Paulo, 50 anos, previamente hígido, com febre 39,2 °C, escarro ferruginoso, FR 31, leucocitose de 22.000 com 15% de bastões, RX com consolidação e broncograma aéreo", "body": "Quadro clássico de PAC; a armadilha é fechar apenas 'pneumonia' na discursiva — a banca exige o sobrenome.", "impact": "Escrever 'pneumonia adquirida na comunidade' garante o ponto. Iniciar β-lactâmico ± macrolídeo conforme risco." },
    { "kicker": "Caso 2", "sourceLabel": "Classificação", "title": "Paciente internado há 72 h para cirurgia eletiva; intubado há 30 h; agora com novo infiltrado e febre", "body": "O delta-T de 48 h de admissão já foi atendido (PAH), mas a VM tem 30 h — abaixo do corte para PAV.", "impact": "É PAH (que precisou de VM), não PAV. Cobertura anti-Pseudomonas; MRSA por risco." },
    { "kicker": "Caso 3", "sourceLabel": "Imagem", "title": "Paciente com clínica muito compatível com pneumonia, RX em PA descrita como normal", "body": "Consolidação retrocardíaca em lobo inferior esquerdo é escondida pela silhueta cardíaca; neutropênico pode não inflamar; problema técnico.", "impact": "Solicitar incidência em perfil, US pulmonar ou TC — não descartar com PA normal." },
    { "kicker": "Caso 4", "sourceLabel": "CURB-65", "title": "Triatleta de 68 anos, hígido, com PAC leve, SpO₂ 96%, ureia normal — CURB-65 1 (só idade)", "body": "Score sugere hospital, mas contexto permite casa: paciente ativo, com suporte, sem dessaturação.", "impact": "O médico decide; score é norte. Alta com orientação e retorno em 48-72 h." },
    { "kicker": "Caso 5", "sourceLabel": "Enfermaria", "title": "PAC moderada internada em enfermaria, sem exposição a água, sem sintomas GI, sem hiponatremia", "body": "Armadilha clássica INEP: contexto permite monoterapia β-lactâmica quando Legionella é clinicamente excluída.", "impact": "Ceftriaxone isolado pode ser a resposta — mas na prática, cobertura dupla é mais segura." },
    { "kicker": "Caso 6", "sourceLabel": "Derrame", "title": "PAC com derrame, laurel > 1 cm, líquido com pH 7,1, glicose 30 mg/dL, LDH 1200", "body": "Derrame parapneumônico complicado — pH, glicose e LDH atendem critérios.", "impact": "Indicação direta de drenagem torácica + ATB. Se loculado: rtPA + DNase ou VATS." },
    { "kicker": "Caso 7", "sourceLabel": "Aspiração", "title": "Paciente rebaixado aspira conteúdo gástrico; 6 horas depois, dispneia, tosse, infiltrado bilateral", "body": "Tempo de horas + aspiração documentada = pneumonite química (Mendelssohn).", "impact": "Suporte ventilatório; ATB NÃO de rotina — introduzir só se infecção secundária em 48-72 h." },
    { "kicker": "Caso 8", "sourceLabel": "Influenza", "title": "Paciente com influenza confirmada há 5 dias, melhora parcial, depois retorna com febre alta, consolidação nova, desvio à esquerda", "body": "Duplo pico em influenza = coinfecção bacteriana secundária.", "impact": "Pensar em pneumococo e S. aureus (MRSA possível). Iniciar ceftriaxone ± vancomicina conforme risco; manter oseltamivir se ainda em atividade viral." }
